function drawNinetalesMoonFox(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 2.8;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 32 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Chùm 9 đuôi hình quạt
  const tailAngles = [-48, -36, -24, -12, 0, 12, 24, 36, 48];
  tailAngles.forEach((ang, i) => {
    const wave = Math.sin(breathPhase - 0.35 * i) * 3.5;
    const tx = -4 + ang * 0.7 + wave;
    const ty = by + 2 - Math.cos(ang * 0.035) * 16.0;
    ctx.fillStyle = '#fef08a';
    ctx.beginPath(); ctx.arc(tx, ty - 2, 7, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#f97316';
    ctx.beginPath(); ctx.moveTo(tx - 4, ty - 6); ctx.lineTo(tx, ty - 16); ctx.lineTo(tx + 4, ty - 6); ctx.fill();
  });

  // 3. Thân & Ngực
  ctx.fillStyle = '#fef9c3';
  ctx.beginPath(); ctx.ellipse(-2, by + 14, 14 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(-6, by + 12, 6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(0,  by + 14, 5, 0, Math.PI * 2); ctx.fill();

  // 4. 4 Chân
  ctx.fillStyle = '#fef9c3';
  [-12, -4].forEach(x => {
    ctx.beginPath(); ctx.roundRect(x, by + 22, 5, 18, 2); ctx.fill();
  });
  ctx.beginPath(); ctx.roundRect(4, by + 24, 6, 16, 2); ctx.fill();

  // 5. Đầu & Mõm
  ctx.beginPath(); ctx.ellipse(-6, by - 8, 14 * sX, 12 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-18, by - 6); ctx.lineTo(-8, by - 12); ctx.lineTo(-8, by - 2); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(-18, by - 6, 2, 2);

  // 6. Đôi tai
  ctx.fillStyle = '#fef9c3';
  ctx.beginPath(); ctx.moveTo(-8, by - 14); ctx.lineTo(-14, by - 36); ctx.lineTo(-2, by - 18); ctx.fill();
  ctx.beginPath(); ctx.moveTo(0,  by - 14); ctx.lineTo(4,   by - 34); ctx.lineTo(8,  by - 16); ctx.fill();
  ctx.fillStyle = '#fde047';
  ctx.beginPath(); ctx.moveTo(-7, by - 16); ctx.lineTo(-12, by - 32); ctx.lineTo(-3, by - 20); ctx.fill();
  ctx.beginPath(); ctx.moveTo(1,  by - 16); ctx.lineTo(4,   by - 30); ctx.lineTo(7,  by - 18); ctx.fill();

  // 7. Bờm tóc gáy
  ctx.fillStyle = '#fef9c3';
  ctx.beginPath(); ctx.moveTo(2, by - 12); ctx.lineTo(22, by - 28); ctx.lineTo(10, by - 6); ctx.fill();

  // 8. Mắt ruby
  if (!blink) {
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.ellipse(-10, by - 8, 2, 4, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-11, by - 9, 1, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-12, by - 8); ctx.lineTo(-8, by - 8); ctx.stroke();
  }

  ctx.restore();
}
